/**
 * Reading direction helper for the JS-driven interactions that CSS logical
 * properties can't reach on their own -- swipe-to-navigate and the horizontal
 * fade-edge masks. CSS handles the rest (logical `start`/`end` utilities).
 *
 * Prefers the computed `direction` (so a CSS-set direction is honoured), and
 * falls back to the nearest `[dir]` attribute when computed style is
 * unavailable (e.g. jsdom in tests, or a detached node). The apps set
 * `<html dir="rtl">` via the i18n bootstrap, so the attribute path is the
 * common one in this repo.
 */
export function isRTL(el?: Element | null): boolean {
  if (typeof document === "undefined") return false;
  const target = el ?? document.documentElement;
  const computed =
    typeof getComputedStyle === "function" ? getComputedStyle(target).direction : "";
  if (computed === "rtl") return true;
  if (computed === "ltr") return false;
  const dirEl = target.closest?.("[dir]") ?? document.documentElement;
  return dirEl.getAttribute("dir") === "rtl";
}
